INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ping6 nur für IPv6-Adressen nötig?', 2, '[{"text": "Ja", "correct": true, "because": "Spezifisch für IPv6"}, {"text": "Nein", "correct": false, "because": "ping kann IPv6 oft auch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option begrenzt die Anzahl der Ping-Anfragen?', 3, '[{"text": "-c", "correct": true, "because": "Setzt Paketanzahl"}, {"text": "-s", "correct": false, "because": "Ändert Paketgröße"}, {"text": "-t", "correct": false, "because": "Timeout, nicht Anzahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen kann ich mit ping6 nutzen?', 5, '[{"text": "-c 10", "correct": true, "because": "10 Pakete senden"}, {"text": "-s 100", "correct": true, "because": "Paketgröße 100 Byte"}, {"text": "-p", "correct": false, "because": "Pattern, nicht Standard"}, {"text": "-d", "correct": false, "because": "Debug, nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) -c stoppt nach fester Anzahl. b) -s ändert die Latenz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "-s beeinflusst Größe, nicht Latenz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei ping6-Optionen?', 4, '[{"text": "-c", "correct": false, "because": "Kontrolliert Anzahl"}, {"text": "-s", "correct": false, "because": "Definiert Paketgröße"}, {"text": "-x", "correct": true, "because": "Keine Standardoption"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob -s die Standardgröße ändert?', 2, '[{"text": "Ja", "correct": true, "because": "Passt Paketgröße an"}, {"text": "Nein", "correct": false, "because": "Standard ist anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option setzt genau 5 Pings?', 3, '[{"text": "-c 5", "correct": true, "because": "Begrenzt auf 5 Pakete"}, {"text": "-s 5", "correct": false, "because": "Größe, nicht Anzahl"}, {"text": "-n 5", "correct": false, "because": "Numerische Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Effekte haben ping6-Optionen?', 5, '[{"text": "-c begrenzt Pakete", "correct": true, "because": "Stoppt nach Anzahl"}, {"text": "-s erhöht Paketgröße", "correct": true, "because": "Mehr Daten pro Ping"}, {"text": "-c ändert Latenz", "correct": false, "because": "Nur Anzahl"}, {"text": "-s komprimiert Daten", "correct": false, "because": "Nur Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) -c 10 sendet 10 Pings. b) -s 0 macht Pakete leer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "-s 0 ist minimal, nicht leer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ping6?', 4, '[{"text": "-c", "correct": false, "because": "Nützlich für Begrenzung"}, {"text": "-s", "correct": false, "because": "Passt Größe an"}, {"text": "-z", "correct": true, "because": "Keine Standardoption"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ändert -s die Anzahl der Pings?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Paketgröße"}, {"text": "Ja", "correct": "false", "because": "Verwechselt mit -c"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option hilft mir, die Paketgröße zu testen?', 4, '[{"text": "-s", "correct": true, "because": "Definiert Größe in Bytes"}, {"text": "-c", "correct": false, "because": "Begrenzt Anzahl"}, {"text": "-n", "correct": false, "because": "Numerische Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass -c unendlich sendet. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Begrenzt, ohne -c ist unendlich"}, {"text": "Ja", "correct": false, "because": "Missverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei ping6 für eine schnelle Diagnose?', 3, '[{"text": "-c", "correct": true, "because": "Begrenzt Testdauer"}, {"text": "-s", "correct": false, "because": "Größe sekundär"}, {"text": "-t", "correct": false, "because": "Timeout, nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) -s 500 sendet 500 Byte. b) -c ist optional.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Beide sind korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten ping6-Optionen?', 5, '[{"text": "Kontrolle der Anzahl", "correct": true, "because": "-c begrenzt"}, {"text": "Testet Paketgröße", "correct": true, "because": "-s passt an"}, {"text": "Verschlüsselt Daten", "correct": false, "because": "Nicht Ping-Funktion"}, {"text": "Ändert Protokoll", "correct": false, "because": "ICMPv6 bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei ping6-Optionen unwichtig?', 3, '[{"text": "-c", "correct": false, "because": "Kontrolliert Anzahl"}, {"text": "-s", "correct": false, "because": "Definiert Größe"}, {"text": "-y", "correct": true, "because": "Keine Standardoption"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Setzt -c die Paketgröße?', 3, '[{"text": "Nein", "correct": true, "because": "Das macht -s"}, {"text": "Ja", "correct": false, "because": "Verwechselt mit -s"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob -s die Latenz direkt beeinflusst?', 2, '[{"text": "Nein", "correct": true, "because": "Nur indirekt via Größe"}, {"text": "Ja", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Option wähle ich für genau 20 Pings?', 4, '[{"text": "-c 20", "correct": true, "because": "Begrenzt auf 20 Pakete"}, {"text": "-s 20", "correct": false, "because": "Größe, nicht Anzahl"}, {"text": "-t 20", "correct": false, "because": "Timeout, nicht Anzahl"}]');
